(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.02-t*0.25)*15;
  const w1y = Math.cos(y*0.015-t*0.28)*20 + Math.sin(x*0.018+t*0.32)*15;
