    const d2 = Math.sqrt((ox-sX)**2 + (oy-sY)**2);
    const att = 1.0/(1.0+d*0.003);
    aS += Math.sin(d*f - t*sp)*w*att;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w*att;
    aS2 += Math.sin(d2*f*0.9 - t*sp*1.1 + 0.8)*w*att;
    iS2 += Math.sin(d2*f*0.6 + t*sp*0.5 + 2.0)*w*att;
    tw += w*att;
  }
  const act = (aS+aS2*0.5)/(tw*1.5), inh = (iS+iS2*0.5)/(tw*1.5);
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+Math.cos(sy*0.06+t)*2+t*1.5)*0.15;
