  const c1 = Math.sin(sx*0.15)*Math.sin(sy*0.15), c2 = Math.sin((sx+sy)*0.1+t)*0.5, c3 = Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3;
  const cell = Math.tanh((c1+c2+c3)*1.5)*0.3;
  const feed = 0.055+Math.sin(t*0.2)*0.01, kill = 0.062+Math.cos(t*0.15)*0.008;
  const rd = act-inh*(kill/feed)+bg*0.3+spiral*0.4+rings*0.2+moire;
