  const pal = [[5,12,52],[10,45,85],[15,85,115],[25,140,135],[60,175,140],[140,195,120],[210,195,80],[230,165,65],[220,120,75],[195,75,85],[145,45,75],[75,22,58],[35,15,48],[5,12,52]];
